    /**
     Checks if the given form-listed element is associated with (owned by) this form, per HTML form ownership rules:
     an explicit {@code form} attribute takes precedence and is resolved against the current document; otherwise the
     control belongs to its nearest ancestor form; otherwise to a form it was linked with during the parse (e.g. a
     control foster-parented out of a table) or via {@link #addElement(Element)}.
     */
    private boolean owns(Element el) {
        if (el.hasAttr("form")) {
            // an explicit form attribute associates the control with the first form in the document with that ID,
            // even if the control is not a descendant of the form; a missing or empty ID associates with no form
            String id = el.attr("form");
            if (id.isEmpty()) return false;
            Document doc = el.ownerDocument();
            if (doc == null) return false;
            for (Element candidate : doc.getElementsByAttributeValue("id", id)) {
                if (candidate.nameIs("form"))
                    return candidate == this;
            }
            return false;
        }

        // no form attribute: the control belongs to its nearest ancestor form, if any
        Node parent = el.parent();
        while (parent != null) {
            if (parent instanceof Element && parent.nameIs("form"))
                return parent == this;
            parent = parent.parent();
        }

        // not currently a descendant of any form; may have been linked during the parse (e.g. foster-parented out of
        // a table) or explicitly added
        return linkedEls.contains(el);
    }
